// === Tab: mySketch ===


Particle [] p = new Array(822);

function setup(){
  createCanvas(800, 800);
  background(0);
	colorMode(HSB,360,100,100);
  noStroke();
  for(i = 0; i < 822; i++){
    p[i] = new Particle();
  }
}

function draw(){
  fill(0,10);
  rect(0,0,width,height);
  for(i = 0; i < 822; i++){
    p[i].display();
    p[i].check();
    p[i].move();
  }
}

// === Tab: tab2 ===
class Particle{

  x, y, ra, vm;
  d,s,b;
  f;
  let v = new PVector();

  constructor(){
    ra = random(1,3);
    x = random(ra,width-ra);
    y = random(ra,height-ra);
    d = int(random(10,100));
    let a = random(0,1);
    vm = random(1,5);
    if(a < 0.25){
      v.x = vm; v.y = 0;}
    else
    if(a < 0.5) {
      v.x = -vm; v.y = 0;}
    else
    if(a < 0.75) {
      v.x = 0; v.y = vm;}
    else {
      v.x = 0; v.y = -vm;}
		s = random(100);
		b = random(100);
    f = color(20,s,b);
  }

  function display(){
		changecolor();
    fill(f);
    ellipse(x,y,2*ra,2*ra);
  }

  function changecolor(){
		f = color(20+frameCount%360,s,b);
	}

  function move(){
    if(d > 0){
      x += v.x;
      y += v.y;
      d--;
    }
    else{
    var a = random(0,1);
    vm = random(1,5);
    if(a < 0.25){
      v.x = vm; v.y = 0;}
    else
    if(a < 0.5) {
      v.x = -vm; v.y = 0;}
    else
    if(a < 0.75) {
      v.x = 0; v.y = vm;}
    else {
      v.x = 0; v.y = -vm;}
    d = int(random(10,100));
    }   
  } 


  function check(){
  if ((x <= ra) || (x >= (width-ra))){
    v.x *= -1;
  }
  if ((y <= ra) || (y >= (height -ra))){
    v.y *= -1;
  }

  }

}

